modules.modules.difficulty:
-- Cross-stage difficulty ramp. Returns a scalar the spawner uses to compress spawn
-- intervals (denser) as stages progress; stages also carry per-segment scroll_mult/
-- drain for hand-tuned escalation within a stage. Pure.
local M = {}

-- difficulty scalar for stage N (1-based): 1.0 at stage 1, ~12% denser per stage.
function M.for_stage(n)
  return 1.0 + 0.12 * ((n or 1) - 1)
end

return M

modules.modules.stairs:
local M = {}
M.x = { L = 540, R = 740 }

function M.new()
  return { lane = "L" }
end

function M.select(s, lane)
  if not M.x[lane] then return false end
  s.lane = lane
  return true
end

return M
